    fileName: "BlockCareer1.vue",
    file: '<template>\n  <!-- \n    Simple centered career listing\n    Features: Centered header, clean job list with badges, location and employment type\n  -->\n  <Motion\n    initial="initial"\n    while-in-view="animate"\n    :in-view-options="{ once: true }"\n    as-child\n    :variants="{\n      initial: { opacity: 0 },\n      animate: {\n        opacity: 1,\n        transition: {\n          when: \'beforeChildren\',\n          delayChildren: stagger(0.1),\n        },\n      },\n    }"\n  >\n    <UiContainer class="pb-16">\n      <UiContainer class="py-16 text-center lg:py-24">\n        <Motion\n          as="h2"\n          :variants="childVariant"\n          class="mt-2 mb-4 text-4xl font-bold lg:mt-3 lg:mb-6 lg:text-5xl"\n        >\n          Open positions\n        </Motion>\n        <Motion\n          as="p"\n          :variants="childVariant"\n          class="text-muted-foreground mx-auto max-w-[800px] text-lg lg:text-xl"\n        >\n          We\'re a 100% remote team spread all across the world. Join us!\n        </Motion>\n      </UiContainer>\n\n      <ul class="mx-auto flex max-w-[768px] flex-col gap-8">\n        <Motion\n          v-for="n in 4"\n          :key="n"\n          :variants="childVariant"\n          :transition="{\n            delay: n * 0.05,\n          }"\n          as="li"\n          class="group hover:border-primary/50 border-t pt-6 transition-colors"\n        >\n          <div class="flex flex-wrap items-center gap-2">\n            <span class="group-hover:text-primary text-lg font-semibold transition-colors"\n              >Product Designer</span\n            >\n            <UiBadge class="text-sm font-medium" variant="outline">Design</UiBadge>\n          </div>\n          <p class="text-muted-foreground mt-2">\n            We\'re looking for a mid-level product designer to join our team.\n          </p>\n          <ul class="mt-5 flex flex-wrap items-center gap-5">\n            <li class="text-muted-foreground flex items-center gap-2">\n              <Icon class="opacity-80" name="heroicons:map-pin" /> Remote\n            </li>\n            <li class="text-muted-foreground flex items-center gap-2">\n              <Icon class="opacity-80" name="heroicons:clock" /> Full-time\n            </li>\n            <li class="md:ml-auto">\n              <UiButton\n                variant="ghost"\n                size="sm"\n                class="group-hover:bg-primary group-hover:text-primary-foreground hover:bg-primary/90"\n              >\n                View details\n                <Icon\n                  name="lucide:arrow-right"\n                  class="ml-2 h-4 w-4 transition-transform group-hover:translate-x-1"\n                />\n              </UiButton>\n            </li>\n          </ul>\n        </Motion>\n      </ul>\n    </UiContainer>\n  </Motion>\n</template>\n\n<script lang="ts" setup>\n  import { stagger } from "motion-v";\n  import type { MotionProps } from "motion-v";\n\n  const childVariant: MotionProps["variants"] = {\n    initial: { opacity: 0, y: 20 },\n    animate: {\n      opacity: 1,\n      y: 0,\n      transition: {\n        type: "spring",\n        stiffness: 200,\n        damping: 20,\n      },\n    },\n  };\n</script>\n',
    category: "Career",
    description:
      "Simple centered career listing. Features: Centered header, clean job list with badges, location and employment type",
    path: "Career/BlockCareer1.vue",
    components: ["badge", "button", "container"],
