    file: '<template>\n  <div class="h-[550px] w-full">\n    <UiApexchart width="100%" height="100%" type="line" :options="options" :series="series" />\n  </div>\n</template>\n\n<script lang="ts" setup>\n  import type { ApexOptions } from "apexcharts";\n\n  const series: ApexOptions["series"] = [\n    {\n      name: "Series 1",\n      data: [500, 1200, 250, 750, 900, 1800, 350, 650, 2100, 300, 800, 1600],\n      color: "var(--color-violet-400)", // Example color\n    },\n    {\n      name: "Series 2",\n      data: [50, 25, 70, 10, 2000, 100, 5, 150, 180, 3000, 120, 800],\n      color: "var(--color-violet-700)", // Example color\n    },\n    {\n      name: "Series 3",\n      data: [3000, 150, 2500, 50, 800, 200, 400, 1000, 1200, 10, 5000, 300],\n      color: "var(--color-violet-900)", // Example color\n    },\n  ];\n\n  const options: ApexOptions = {\n    stroke: {\n      width: 3,\n      curve: "smooth",\n      lineCap: "round",\n    },\n    legend: {\n      fontFamily: "inherit",\n      fontWeight: 500,\n      offsetY: 5,\n      labels: {\n        colors: "var(--color-muted-foreground)",\n      },\n    },\n    grid: {\n      borderColor: "var(--color-border)",\n    },\n    chart: {\n      toolbar: {\n        show: window.innerWidth > 768,\n      },\n    },\n    yaxis: {\n      title: {\n        text: window.innerWidth > 768 ? "Active users" : "",\n        offsetX: 5,\n        style: {\n          fontWeight: 600,\n          fontSize: "13px",\n          color: "var(--color-muted-foreground)",\n          fontFamily: "inherit",\n        },\n      },\n      labels: {\n        style: {\n          colors: "var(--color-muted-foreground)",\n          fontFamily: "inherit",\n        },\n      },\n    },\n    xaxis: {\n      title: {\n        text: window.innerWidth > 768 ? "Months" : "",\n        offsetY: -2,\n        style: {\n          fontWeight: 600,\n          fontSize: "13px",\n          color: "var(--color-muted-foreground)",\n          fontFamily: "inherit",\n        },\n      },\n      labels: {\n        style: {\n          colors: "var(--color-muted-foreground)",\n          fontFamily: "inherit",\n        },\n      },\n\n      categories: [\n        "Jan",\n        "Feb",\n        "Mar",\n        "Apr",\n        "May",\n        "Jun",\n        "Jul",\n        "Aug",\n        "Sep",\n        "Oct",\n        "Nov",\n        "Dec",\n      ],\n    },\n  };\n</script>\n',
