    file: '<template>\n  <UiSidebarProvider>\n    <UiSidebarInset>\n      <header class="flex h-16 shrink-0 items-center gap-2 border-b px-4">\n        <UiBreadcrumbs :items="breadcrumbItems" />\n        <UiSidebarTrigger class="-mr-1 ml-auto rotate-180" />\n      </header>\n      <div class="flex flex-1 flex-col gap-4 p-4">\n        <div class="grid auto-rows-min gap-4 md:grid-cols-3">\n          <UiPlaceholder v-for="n in 3" :key="n" class="aspect-video rounded-xl" />\n        </div>\n        <UiPlaceholder class="min-h-screen flex-1 rounded-xl md:min-h-min" />\n      </div>\n    </UiSidebarInset>\n    <!-- Main Sidebar -->\n    <UiSidebar side="right">\n      <UiSidebarContent>\n        <UiSidebarGroup>\n          <UiSidebarGroupLabel label="Table of Contents" />\n          <UiSidebarGroupContent>\n            <UiSidebarMenu>\n              <UiSidebarMenuItem v-for="item in data.navMain" :key="item.title">\n                <UiSidebarMenuButton as-child>\n                  <NuxtLink :href="item.url" class="font-medium">\n                    {{ item.title }}\n                  </NuxtLink>\n                </UiSidebarMenuButton>\n                <UiSidebarMenuSub v-if="item.items?.length">\n                  <UiSidebarMenuSubItem v-for="(child, index) in item.items" :key="index">\n                    <UiSidebarMenuSubButton as-child :is-active="child.isActive">\n                      <NuxtLink :href="child.url">{{ child.title }}</NuxtLink>\n                    </UiSidebarMenuSubButton>\n                  </UiSidebarMenuSubItem>\n                </UiSidebarMenuSub>\n              </UiSidebarMenuItem>\n            </UiSidebarMenu>\n          </UiSidebarGroupContent>\n        </UiSidebarGroup>\n      </UiSidebarContent>\n      <UiSidebarRail />\n    </UiSidebar>\n  </UiSidebarProvider>\n</template>\n\n<script lang="ts" setup>\n  useSeoMeta({ title: "A sidebar on the right." });\n  const breadcrumbItems = [\n    { label: "Building Your Application", href: "#" },\n    { label: "Data Fetching", href: "#" },\n  ];\n  const data = {\n    navMain: [\n      {\n        title: "Getting Started",\n        url: "#",\n        items: [\n          { title: "Installation", url: "#" },\n          { title: "Project Structure", url: "#" },\n        ],\n      },\n      {\n        title: "Building Your Application",\n        url: "#",\n        items: [\n          { title: "Routing", url: "#" },\n          { title: "Data Fetching", url: "#", isActive: true },\n          { title: "Rendering", url: "#" },\n          { title: "Caching", url: "#" },\n          { title: "Styling", url: "#" },\n          { title: "Optimizing", url: "#" },\n          { title: "Configuring", url: "#" },\n          { title: "Testing", url: "#" },\n          { title: "Authentication", url: "#" },\n          { title: "Deploying", url: "#" },\n          { title: "Upgrading", url: "#" },\n          { title: "Examples", url: "#" },\n        ],\n      },\n      {\n        title: "API Reference",\n        url: "#",\n        items: [\n          { title: "Components", url: "#" },\n          { title: "File Conventions", url: "#" },\n          { title: "Functions", url: "#" },\n          { title: "next.config.js Options", url: "#" },\n          { title: "CLI", url: "#" },\n          { title: "Edge Runtime", url: "#" },\n        ],\n      },\n      {\n        title: "Architecture",\n        url: "#",\n        items: [\n          { title: "Accessibility", url: "#" },\n          { title: "Fast Refresh", url: "#" },\n          { title: "Next.js Compiler", url: "#" },\n          { title: "Supported Browsers", url: "#" },\n          { title: "Turbopack", url: "#" },\n        ],\n      },\n      {\n        title: "Community",\n        url: "#",\n        items: [{ title: "Contribution Guide", url: "#" }],\n      },\n    ],\n  };\n</script>\n',
