    file: '<template>\n  <!--\n    Founders story with a team strip\n    Features: Two founder portraits with a short note each and signature style role, an overlapping avatar strip of the rest of the team and a hiring link\n  -->\n  <UiContainer class="py-16 lg:py-24">\n    <div class="mx-auto max-w-2xl text-center">\n      <h2 class="text-3xl font-bold tracking-tight text-balance sm:text-4xl">{{ props.title }}</h2>\n      <p class="text-muted-foreground mt-3 text-lg text-balance">{{ props.description }}</p>\n    </div>\n    <div class="mt-12 grid gap-8 md:grid-cols-2">\n      <Motion\n        v-for="(m, i) in props.members.slice(0, 2)"\n        :key="m.name"\n        :initial="{ opacity: 0, y: 20 }"\n        :while-in-view="{ opacity: 1, y: 0 }"\n        :in-view-options="{ once: true }"\n        :transition="{ duration: 0.45, delay: i * 0.12 }"\n        class="bg-card overflow-hidden rounded-3xl border"\n      >\n        <div class="aspect-16/10 overflow-hidden">\n          <img\n            :src="m.avatar"\n            :alt="m.name"\n            class="size-full object-cover object-top"\n            loading="lazy"\n          />\n        </div>\n        <div class="p-6 sm:p-8">\n          <p class="text-lg leading-relaxed">“{{ m.bio }}”</p>\n          <div class="mt-5 flex items-center justify-between gap-3">\n            <div>\n              <p class="font-semibold">{{ m.name }}</p>\n              <p class="text-muted-foreground text-sm">{{ m.role }}</p>\n            </div>\n            <div class="flex items-center gap-3">\n              <a\n                v-if="m.x"\n                :href="m.x"\n                :aria-label="`${m.name} on X`"\n                class="text-muted-foreground hover:text-foreground transition-colors"\n                ><Icon name="simple-icons:x" class="size-4"\n              /></a>\n              <a\n                v-if="m.linkedin"\n                :href="m.linkedin"\n                :aria-label="`${m.name} on LinkedIn`"\n                class="text-muted-foreground hover:text-foreground transition-colors"\n                ><Icon name="mdi:linkedin" class="size-5"\n              /></a>\n              <a\n                v-if="m.github"\n                :href="m.github"\n                :aria-label="`${m.name} on GitHub`"\n                class="text-muted-foreground hover:text-foreground transition-colors"\n                ><Icon name="mdi:github" class="size-5"\n              /></a>\n            </div>\n          </div>\n        </div>\n      </Motion>\n    </div>\n    <div class="mt-12 flex flex-col items-center gap-4 text-center">\n      <UiAvatarGroup>\n        <UiAvatar v-for="m in props.members.slice(2)" :key="m.name" class="size-12">\n          <UiAvatarImage :src="m.avatar" :alt="m.name" />\n          <UiAvatarFallback>{{ m.name[0] }}</UiAvatarFallback>\n        </UiAvatar>\n      </UiAvatarGroup>\n      <p class="text-muted-foreground text-sm">and 40 more teammates across 19 countries</p>\n      <UiButton variant="link">\n        See open positions\n        <Icon name="lucide:arrow-right" class="size-4" />\n      </UiButton>\n    </div>\n  </UiContainer>\n</template>\n\n<script lang="ts" setup>\n  type Member = {\n    name: string;\n    role: string;\n    department: string;\n    location: string;\n    bio: string;\n    avatar: string;\n    x?: string;\n    linkedin?: string;\n    github?: string;\n  };\n\n  const props = withDefaults(\n    defineProps<{ title?: string; description?: string; members?: Member[] }>(),\n    {\n      title: "Built by two friends who wanted better tools",\n      description: "What started in a spare bedroom is now a team that ships every week.",\n      members: () => [\n        {\n          name: "Maya Chen",\n          role: "Co-founder & CEO",\n          department: "Leadership",\n          location: "San Francisco, US",\n          bio: "Former product lead who has launched three companies. Obsessed with calm software.",\n          avatar: "https://i.pravatar.cc/400?img=47",\n          x: "#",\n          linkedin: "#",\n        },\n        {\n          name: "Liam O\'Connor",\n          role: "Co-founder & CTO",\n          department: "Leadership",\n          location: "Dublin, IE",\n          bio: "Spent a decade building distributed systems before deciding they should be friendlier.",\n          avatar: "https://i.pravatar.cc/400?img=12",\n          github: "#",\n          linkedin: "#",\n        },\n        {\n          name: "Priya Nair",\n          role: "Head of Design",\n          department: "Design",\n          location: "Bengaluru, IN",\n          bio: "Leads a small team that sweats the details, from icons to onboarding.",\n          avatar: "https://i.pravatar.cc/400?img=45",\n          x: "#",\n          linkedin: "#",\n        },\n        {\n          name: "Noah Fischer",\n          role: "Staff Engineer",\n          department: "Engineering",\n          location: "Berlin, DE",\n          bio: "Performance nerd. If it takes more than 100ms, he has already opened a pull request.",\n          avatar: "https://i.pravatar.cc/400?img=53",\n          github: "#",\n          x: "#",\n        },\n        {\n          name: "Ana Souza",\n          role: "Engineering Manager",\n          department: "Engineering",\n          location: "São Paulo, BR",\n          bio: "Coaches engineers, unblocks teams and keeps releases boring in the best way.",\n          avatar: "https://i.pravatar.cc/400?img=44",\n          linkedin: "#",\n          github: "#",\n        },\n        {\n          name: "Sam Okafor",\n          role: "Product Designer",\n          department: "Design",\n          location: "Lagos, NG",\n          bio: "Turns messy ideas into clear flows. Collects keyboards and board games.",\n          avatar: "https://i.pravatar.cc/400?img=32",\n          x: "#",\n          linkedin: "#",\n        },\n        {\n          name: "Hannah Lee",\n          role: "Head of Growth",\n          department: "Growth",\n          location: "Seoul, KR",\n          bio: "Builds the playbooks that bring the right customers through the door.",\n          avatar: "https://i.pravatar.cc/400?img=49",\n          linkedin: "#",\n          x: "#",\n        },\n        {\n          name: "Diego Alvarez",\n          role: "Customer Success Lead",\n          department: "Growth",\n          location: "Mexico City, MX",\n          bio: "First to answer, last to give up. Our customers have his number on speed dial.",\n          avatar: "https://i.pravatar.cc/400?img=33",\n          linkedin: "#",\n        },\n      ],\n    }\n  );\n</script>\n',
